import { fireEvent } from '@testing-library/dom';
import {
    findByText as findByTextDefault,
    getByText as getByTextDefault,
    queryAllByTestId as queryAllByTestIdDefault,
    queryByTestId as queryByTestIdDefault,
} from '@testing-library/react';

import { IMAGE_PROXY_FLAGS, SHOW_IMAGES } from '@proton/shared/lib/constants';

import { setFeatureFlags } from '../../../helpers/test/api';
import { addToCache, minimalCache } from '../../../helpers/test/cache';
import { render } from '../../../helpers/test/render';
import { MessageState } from '../../../logic/messages/messagesTypes';
import HeaderTopPrivacyIcon from '../../message/header/HeaderTopPrivacyIcon';
import ItemSpyTrackerIcon from './ItemSpyTrackerIcon';

const messageWithTrackers: MessageState = {
    localID: 'messageWithTrackerId',
    messageImages: {
        hasEmbeddedImages: true,
        hasRemoteImages: false,
        showEmbeddedImages: true,
        showRemoteImages: true,
        images: [
            {
                type: 'embedded',
                id: 'imageID',
                status: 'loaded',
                tracker: 'Tracker 1',
                cid: 'cid',
                cloc: 'cloc',
                attachment: {},
            },
            {
                type: 'embedded',
                id: 'imageID',
                status: 'loaded',
                tracker: 'Tracker 2',
                cid: 'cid',
                cloc: 'cloc',
                attachment: {},
            },
        ],
    },
};

const messageWithoutTrackers: MessageState = {
    localID: 'messageWithoutTrackerId',
    messageImages: {
        hasEmbeddedImages: true,
        hasRemoteImages: false,
        showEmbeddedImages: true,
        showRemoteImages: true,
        images: [
            {
                type: 'embedded',
                id: 'imageID',
                status: 'loaded',
                tracker: undefined,
                cid: 'cid',
                cloc: 'cloc',
                attachment: {},
            },
        ],
    },
};

describe('ItemSpyTrackerIcon', () => {
    it.each`
        imageProxy                | showImage           | message                   | isIconDisplayed | isNumberDisplayed | expectedTooltip
        ${IMAGE_PROXY_FLAGS.ALL}  | ${SHOW_IMAGES.SHOW} | ${messageWithTrackers}    | ${true}         | ${true}           | ${'2 email trackers blocked'}
        ${IMAGE_PROXY_FLAGS.ALL}  | ${SHOW_IMAGES.SHOW} | ${messageWithoutTrackers} | ${true}         | ${false}          | ${'No email trackers found'}
        ${IMAGE_PROXY_FLAGS.ALL}  | ${SHOW_IMAGES.HIDE} | ${messageWithTrackers}    | ${true}         | ${true}           | ${'2 email trackers blocked'}
        ${IMAGE_PROXY_FLAGS.ALL}  | ${SHOW_IMAGES.HIDE} | ${messageWithoutTrackers} | ${true}         | ${false}          | ${'No email trackers found'}
        ${IMAGE_PROXY_FLAGS.NONE} | ${SHOW_IMAGES.HIDE} | ${messageWithTrackers}    | ${true}         | ${true}           | ${'Email tracker protection is disabled'}
        ${IMAGE_PROXY_FLAGS.NONE} | ${SHOW_IMAGES.HIDE} | ${messageWithoutTrackers} | ${true}         | ${false}          | ${'Email tracker protection is disabled'}
        ${IMAGE_PROXY_FLAGS.NONE} | ${SHOW_IMAGES.SHOW} | ${messageWithTrackers}    | ${true}         | ${true}           | ${'2 email trackers blocked'}
        ${IMAGE_PROXY_FLAGS.NONE} | ${SHOW_IMAGES.SHOW} | ${messageWithoutTrackers} | ${false}        | ${false}          | ${''}
    `(
        'should display the icon [$isIconDisplayed] with number [$isNumberDisplayed] and tooltip [$expectedTooltip]',
        async ({ imageProxy, showImage, message, isIconDisplayed, isNumberDisplayed, expectedTooltip }) => {
            minimalCache();
            setFeatureFlags('SpyTrackerProtection', true);
            addToCache('MailSettings', { ImageProxy: imageProxy, HideRemoteImages: showImage });

            const { getByTestId, queryByTestId, getAllByText } = await render(
                <ItemSpyTrackerIcon message={message} />,
                false
            );

            const icon = queryByTestId('privacy:tracker-icon');

            if (!isIconDisplayed) {
                // When icon is not displayed, we don't have a tooltip or the number either
                expect(icon).toBeNull();
            } else {
                // In every other cases, the icon should be displayed
                expect(icon).toBeTruthy();

                // Check that the number of trackers is displayed when we want to display it
                const numberOfTrackers = queryByTestId('privacy:icon-number-of-trackers');
                if (isNumberDisplayed) {
                    expect(numberOfTrackers).toBeTruthy();
                    expect(numberOfTrackers?.innerHTML).toEqual('2');
                } else {
                    expect(numberOfTrackers).toBeNull();
                }

                // Check the text of the Tooltip
                const tooltip = getByTestId('privacy:icon-tooltip');
                fireEvent.mouseOver(tooltip);
                getAllByText(expectedTooltip);
            }
        }
    );

    it('should open a modal with "No email trackers found" title', async () => {
        minimalCache();
        setFeatureFlags('SpyTrackerProtection', true);
        addToCache('MailSettings', { ImageProxy: IMAGE_PROXY_FLAGS.ALL, HideRemoteImages: SHOW_IMAGES.SHOW });

        const { findByTestId } = await render(<HeaderTopPrivacyIcon message={messageWithoutTrackers} />, false);

        const icon = await findByTestId('privacy:tracker-icon');
        fireEvent.click(icon);

        const modal = await findByTestId('spyTrackerModal:noTrackers');
        getByTextDefault(modal, 'No email trackers found');
    });
import React, { useRef } from 'react';

import { FeatureCode, Tooltip, classnames, useSpotlightOnFeature } from '@proton/components';
import useUser from '@proton/components/hooks/useUser';
import { MONTH } from '@proton/shared/lib/constants';
import { isSent } from '@proton/shared/lib/mail/messages';

import { useMessageTrackers } from '../../../hooks/message/useMessageTrackers';
import { MessageState } from '../../../logic/messages/messagesTypes';
import LoadContentSpotlight from '../../message/LoadContentSpotlight';
import SpyTrackerIcon from './SpyTrackerIcon';

interface Props {
    message: MessageState;
    className?: string;
    onClickIcon?: () => void;
}

const ItemSpyTrackerIcon = ({ message, className, onClickIcon }: Props) => {
    // TODO On the first part of the SL integration we will not have the change on the icon. We already started the implementation so we will hide it for now
    // const { feature: simpleLoginIntegration, loading: loadingSimpleLoginIntegration } = useFeature(
    //     FeatureCode.SLIntegration
    // );

    const [user] = useUser();

    const anchorRef = useRef(null);

    const sent = isSent(message.data);

    const isSimpleLoginIntegration = false; //TODO replace with when we will need simpleLoginIntegration?.Value;

    const { hasProtection, hasShowRemoteImage, numberOfTrackers, needsMoreProtection, title } = useMessageTrackers({
        message,
    });

    // Load content spotlight needs to be displayed if account is older than one month
    const userCreateTime = user.CreateTime || 0;
    const isAccountOlderThanOneMonth = Date.now() > userCreateTime * 1000 + MONTH;

    const { show: showLoadContentSpotlight, onDisplayed: onLoadContentSpotlightDisplayed } = useSpotlightOnFeature(
        FeatureCode.SpotlightLoadContent,
        isAccountOlderThanOneMonth
    );

    /*
     * Don't display the tracker icon on sent mails or when :
     * Loading remote images is automatic and email protection is OFF : We consider that the user don't want any protection at all.
     * But the user might have set recently the protection to OFF, so if we find trackers in previous emails, we still display the icon.
     */
    if (sent || (!hasProtection && hasShowRemoteImage && numberOfTrackers === 0)) {
        // TODO check also loadingSimpleLoginIntegrationFeature
        return null;
    }

    const spyTrackerIcon = (
        <div className={classnames(['flex', className])} ref={anchorRef}>
            <SpyTrackerIcon
                numberOfTrackers={numberOfTrackers}
                needsMoreProtection={needsMoreProtection}
                title={title}
                isStandaloneIcon={!isSimpleLoginIntegration}
                openSpyTrackerModal={onClickIcon}
            />
        </div>
    );

    return (
        <LoadContentSpotlight
            show={showLoadContentSpotlight}
            onDisplayed={onLoadContentSpotlightDisplayed}
            anchorRef={anchorRef}
        >
            {isSimpleLoginIntegration ? (
                <div className="flex flex-nowrap flex-align-items-center">
                    <span className="mr0-5 relative inline-flex item-spy-tracker-link flex-align-items-center">
                        {spyTrackerIcon}
                    </span>
                    <span className="pl0-25 flex-item-fluid" title={title}>
                        {title}
                    </span>
                </div>
            ) : (
                <div>
                    {/* Need to wrap the Tooltip by a div to avoid ref warning because Spotlight is cloning the element and applying refs on top of it */}
                    <Tooltip title={title} data-testid="privacy:icon-tooltip">
                        {spyTrackerIcon}
                    </Tooltip>
                </div>
            )}
        </LoadContentSpotlight>
    );
};

export default ItemSpyTrackerIcon;
